@InvocableMethod(label='Find Region')
public static List<String> findRegion(List<String> zips) {
  List<String> out = new List<String>();
  for (String z : zips) {
    Region__c r = [SELECT Name FROM Region__c WHERE Zip__c = :z LIMIT 1];
    out.add(r.Name);
  }
  return out;
}

